#!/usr/bin/env bash
set -euo pipefail

# rescript clean only knows sources that still belong to the build. Identify
# tracked compiler output from the index so deleted/excluded sources are covered,
# while handwritten JavaScript and configuration remain untouched.
git ls-files -z -- '*.jsx' '*.mjs' |
  while IFS= read -r -d '' output; do
    committed=$(git show ":$output")
    if [[ "$committed" == "// Generated by ReScript,"* ]]; then
      rm -f -- "$output"
    fi
  done
